'use strict';
// Tutorial 2.0: an open relic garden, lesson trail, royal arena and farewell portal.
function tutorialQueenX(){return training?.queenX||5720;}
function updateTutorialExploration(dt){training.queenX+=((training.victoryReady?7180:5720)-training.queenX)*(1-Math.exp(-dt*1.5));for(const r of training.relics){if(!r.taken&&Math.hypot(nessie.x-r.x,nessie.y-r.y)<95){r.taken=true;score+=100;popups.push({x:r.x,y:r.y-85,text:'+100 · A lagoon relic!',life:2,color:'#ffe9ac'});tone(920,.15);tutorialSay(['A golden shell! I wonder who left this here.','Treasure hunting definitely counts as homework.','Three relics! Mum will want these on the mantelpiece.'][training.relics.filter(q=>q.taken).length-1],'sarah',4);}}
 if(training.step===5)training.queenSeen=true;if(training.victoryReady&&!training.sendoff&&nessie.x>7100&&!leap.active){training.sendoff=true;if(mode==='sarah')openDialogue('antonella-sendoff');else tutorialSay('You’re ready. Your adventure is through the portal!','queen',4);}}
function drawTutorialGardens(t){const tick=reducedMotion?0:t;
 // Reuse the painted architecture in low-opacity distant layers, with clear swim lanes.
 ctx.save();for(let i=0;i<12;i++){const x=280+i*630-camera*.8;if(x<-220||x>vw+220)continue;ctx.globalAlpha=.23;envDraw(1,x,430,125,420,tick);ctx.globalAlpha=.34;envDraw(4,x-65,815,260,100,tick,true);}ctx.restore();
 for(const r of training.relics){const x=r.x-camera;if(x<-160||x>vw+160)continue;ctx.save();const glow=ctx.createRadialGradient(x,r.y,5,x,r.y,105);glow.addColorStop(0,r.taken?'#a8ffdd17':'#ffe69b35');glow.addColorStop(1,'#b9ffe700');ctx.fillStyle=glow;ctx.fillRect(x-105,r.y-105,210,210);envDraw(0,x-85,r.y+28,170,110,tick);if(!r.taken){if(!drawRelicArtwork(x,r.y-18,125))drawCueBadge(x,r.y-15,'compass',true,tick);for(let j=0;j<4;j++){const a=j*Math.PI/2+tick*.7;paintedBubble(x+Math.cos(a)*55,r.y-18+Math.sin(a)*30,4,.65);}}ctx.restore();}
 // Antonella has her own little court and remains a friendly spectator.
 if(training.queenSeen||training.step>=5){const qx=tutorialQueenX()-camera;ctx.save();ctx.globalAlpha=.7;envDraw(2,qx-130,645,260,215,tick);ctx.restore();drawRoyalCharacter('queen',qx,470+Math.sin(tick*.8)*8,250,tick,'idle','warm');}
 const ax=6900-camera;if(ax>-700&&ax<vw+700){ctx.save();ctx.globalAlpha=.6;for(const side of [-1,1]){envDraw(1,ax+side*350-60,380,120,495,tick);envDraw(4,ax+side*350-125,830,250,105,tick,true);}ctx.globalAlpha=1;ctx.strokeStyle='#c5fff13b';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(ax,870,330,40,0,0,Math.PI*2);ctx.stroke();for(let i=0;i<9;i++)paintedBubble(ax-290+i*73,857+Math.sin(i*.7)*12,5,.6);ctx.restore();}
}
function drawRelicArtwork(x,y,size){return atlasDraw(tutorialAtlasArt,[.733,.145,.26,.81],x-size*.43,y-size*.5,size*.86,size);}
function drawOrnatePortal(x,y,height,t,open){if(x+height<0||x-height>vw||y+height<0||y-height>H)return;ctx.save();ctx.translate(x,y);const tick=reducedMotion?0:t,rx=height*.28,ry=height*.43;const glow=ctx.createRadialGradient(0,0,5,0,0,height*.65);glow.addColorStop(0,open?'#b7fff544':'#619cb416');glow.addColorStop(1,'#baaeff00');ctx.fillStyle=glow;ctx.fillRect(-height*.65,-height*.65,height*1.3,height*1.3);ctx.save();ctx.beginPath();ctx.ellipse(0,0,rx,ry,0,0,Math.PI*2);ctx.clip();const core=ctx.createRadialGradient(-rx*.3,-ry*.3,3,0,0,ry);core.addColorStop(0,open?'#ddfff9':'#7094ad');core.addColorStop(.45,open?'#7ebde6':'#27445e');core.addColorStop(1,open?'#574caa':'#102b45');ctx.fillStyle=core;ctx.fillRect(-rx,-ry,rx*2,ry*2);if(open)for(let i=0;i<5;i++){ctx.strokeStyle=['#fff3cd99','#acffed88','#d2bcff88'][i%3];ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(Math.sin(tick*.4+i)*rx*.2,Math.cos(tick*.6+i)*ry*.12,rx*(.25+i*.17),ry*(.22+i*.18),tick*.18+i,.3,Math.PI*1.85);ctx.stroke();}ctx.restore();ctx.strokeStyle='#e7d5a2';ctx.lineWidth=8;ctx.beginPath();ctx.ellipse(0,0,rx+7,ry+7,0,0,Math.PI*2);ctx.stroke();for(let i=0;i<18;i++){const a=i/18*Math.PI*2;paintedBubble(Math.cos(a)*(rx+7),Math.sin(a)*(ry+7),3.2,.85);}drawPortalArtwork(0,0,height,open);drawCueBadge(0,-height*.58,open?'portal':'shield',open,tick);ctx.restore();}
function drawPortalArtwork(x,y,height,open){ctx.save();ctx.globalAlpha=open?1:.52;const drawn=atlasDraw(tutorialAtlasArt,[0,0,.336,1],x-height*.42,y-height*.5,height*.84,height);ctx.restore();return drawn;}
function drawPaintedBubbleArtwork(x,y,r,alpha){if(!tutorialAtlasArt?.complete||!tutorialAtlasArt.naturalWidth||r<4)return false;ctx.save();ctx.globalAlpha=alpha*.78;atlasDraw(tutorialAtlasArt,[.362,.07,.34,.855],x-r,y-r,r*2,r*2);ctx.restore();return true;}
function installTutorialTwoDialogue(){conversations['antonella-welcome']={speaker:'Queen Antonella',portrait:'queen-warm',line:'There you are, darling! I brought two gifts.\nSarah: Mum! Are you here for mermaid school too?\nAntonella: I’m here to ensure your father’s lesson includes something other than thunder.\nKing Daddy: AND AN ELITE ROCK.',options:[['What do the gifts do?','The pink heart restores a heart. The gold bubble gives eight seconds of unlimited boost. Collect both, then try a powered jump.'],['Did you hide the relics?','Three little treasures, just for you. They’re optional — curiosity deserves a reward.\nSarah: Best homework ever.'],['Are you watching my big jump?','Every glorious splash. Hold UP and press BOOST after collecting both gifts. If the gold runs out, we’ll refill it.']],hint:''};conversations['antonella-sendoff']={speaker:'Queen Antonella',portrait:'queen-proud',line:'Look at you! A proper adventurer.\nKing Daddy: Trained by the Lord of Thunder!\nAntonella: And supervised by someone sensible.\nSarah: Love you both. Scotland, here I come!',options:[['Through the portal!','Swim into the shining shell gate. Your adventure is waiting.'],['One more family hug?','Always, darling. You can return to this lagoon from Choose a stage whenever you like.']],hint:''};}
